<?php
// Performance measurement on synthetic data (test database only). Seeds volume, times endpoints (median of 5), prints EXPLAIN.
declare(strict_types=1); $cfg = require getenv('LTI_CONFIG'); if (strpos($cfg['db']['name'], 'test') === false) exit("Refusing: not a test database\n");
$pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]); $base = 'http://127.0.0.1:8000/api';
$adv = (int)$pdo->query("SELECT id FROM users WHERE email='advisor@lti.test'")->fetchColumn(); $N = (int)($argv[1] ?? 5000);
if (!empty($argv[2])) { $pdo->exec("SET @i=0"); $pdo->beginTransaction();
  $ins = $pdo->prepare("INSERT INTO contacts (contact_type, first_name, last_name, email, phone, assigned_to, created_by, created_at, updated_at, version) VALUES ('Lead',?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP(),1)");
  for ($i = 0; $i < $N; $i++) $ins->execute(['Perf' . $i, ['Smith', 'Garcia', 'Nguyen', 'Okafor', 'Rossi'][$i % 5], "perf$i@example.test", '+1 415 555 ' . str_pad((string)($i % 10000), 4, '0', STR_PAD_LEFT), $adv, $adv]);
  $c = $pdo->prepare("INSERT INTO calls (mode, source, verification, direction, status, phone, phone_e164, contact_id, staff_id, started_at, duration_seconds, duration_source, created_by, created_at, updated_at, version) VALUES ('phone_handoff','manual_log','user_entered',?,?,?,?,?,?,UTC_TIMESTAMP() - INTERVAL ? MINUTE,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP(),1)");
  $ids = $pdo->query("SELECT id FROM contacts ORDER BY id DESC LIMIT $N")->fetchAll(PDO::FETCH_COLUMN);
  for ($i = 0; $i < $N; $i++) { $st = ['connected', 'no_answer', 'missed'][$i % 3]; $c->execute([$i % 2 ? 'inbound' : 'outbound', $st === 'missed' && $i % 2 === 0 ? 'no_answer' : $st, '+14155550000', '+14155550000', $ids[$i % count($ids)], $adv, $i * 7, $st === 'connected' ? 60 + $i % 600 : null, $st === 'connected' ? 'entered' : 'unknown', $adv]); }
  $t = $pdo->prepare("INSERT INTO tasks (title, due_date, priority, status, assigned_to, contact_id, source, created_by, created_at, updated_at, version) VALUES (?,?,'normal',?,?,?,'Manual',?,UTC_TIMESTAMP(),UTC_TIMESTAMP(),1)");
  for ($i = 0; $i < $N; $i++) $t->execute(['Perf task ' . $i, date('Y-m-d', time() + 86400 * (($i % 60) - 30)), $i % 4 ? 'todo' : 'completed', $adv, $ids[$i % count($ids)], $adv]); $pdo->commit(); }
$jar = tempnam(sys_get_temp_dir(), 'j'); $ch = curl_init("$base/auth/login"); curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_COOKIEJAR => $jar, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode(['email' => 'advisor@lti.test', 'password' => 'Dev-Password-2026'])]); $lr = json_decode((string)curl_exec($ch), true); unset($ch); // PHP 8: the cookie jar is written when the handle is destroyed if (empty($lr['csrf'])) exit("Sign-in failed; no measurement taken\n");
$eps = ['/contacts?page=1&perPage=50', '/contacts?q=garcia', '/calls?perPage=25', '/calls?status=missed', '/calls?q=4155550000', '/calls/report', '/tasks?overdue=1', '/tasks?upcomingDays=7', '/notifications', '/trips?type=all&perPage=50'];
$out = []; foreach ($eps as $e) { $ts = []; $code = 0; for ($k = 0; $k < 5; $k++) { $h = curl_init($base . $e); curl_setopt_array($h, [CURLOPT_RETURNTRANSFER => true, CURLOPT_COOKIEFILE => $jar]); $t0 = microtime(true); curl_exec($h); $ts[] = (microtime(true) - $t0) * 1000; $code = curl_getinfo($h, CURLINFO_HTTP_CODE); }
  if ($code !== 200) exit("$e returned HTTP $code; measurement invalid\n"); sort($ts); $out[] = sprintf('%-32s HTTP %d  median %6.1f ms  max %6.1f ms', $e, $code, $ts[2], $ts[4]); }
echo "Volume: contacts=" . $pdo->query('SELECT COUNT(*) FROM contacts')->fetchColumn() . " calls=" . $pdo->query('SELECT COUNT(*) FROM calls')->fetchColumn() . " tasks=" . $pdo->query('SELECT COUNT(*) FROM tasks')->fetchColumn() . "\n" . implode("\n", $out) . "\n";
foreach (['calls list' => "EXPLAIN SELECT * FROM calls cl WHERE cl.archived_at IS NULL AND cl.staff_id=$adv ORDER BY cl.started_at DESC LIMIT 25", 'overdue tasks' => "EXPLAIN SELECT * FROM tasks k WHERE k.assigned_to=$adv AND k.due_date < CURDATE() AND k.status IN ('todo','in_progress','blocked')", 'contact by phone' => "EXPLAIN SELECT * FROM contact_phones WHERE phone_e164='+14155550123'"] as $n => $q) {
  $r = $pdo->query($q)->fetchAll(PDO::FETCH_ASSOC); echo "EXPLAIN $n: " . implode(' | ', array_map(fn($x) => "{$x['table']} type={$x['type']} key=" . ($x['key'] ?? 'none') . " rows={$x['rows']}", $r)) . "\n"; }
